// Curated readings augment the lessons; they are not substituted for explanations
// and are not represented as independently verified evidence.
export function getPromptEngineeringGuide(lessonId) {
  const guide = promptEngineeringGuides[Number(lessonId)];
  if (!guide) return undefined;
  return { ...guide, resources: supplementalReading[Number(lessonId)] ?? [] };
}
